import csv,json,collections
from pathlib import Path
root=Path(__file__).resolve().parents[1]
events=[]
aliases={'DR Congo (Zaire)':'COD','Myanmar (Burma)':'MMR','Russia (Soviet Union)':'RUS','Yemen (North Yemen)':'YEM','Turkey':'TUR','Iran':'IRN','Syria':'SYR','Venezuela':'VEN','Tanzania':'TZA'}
facts=json.load(open(root/'data/facts_raw.json'))
names={f['name']['common']:f['cca3'] for f in facts};names.update(aliases)
for r in csv.DictReader(open(root/'data/ucdp_raw.csv')):
    events.append({'id':r['id'],'country':r['country'],'code':names.get(r['country'],''),'conflict':r['conflict_name'],'actors':r['dyad_name'],'a':r['side_a'],'b':r['side_b'],'lat':float(r['latitude']),'lon':float(r['longitude']),'location':r['where_coordinates'],'region':r['adm_1'],'type':int(r['type_of_violence']),'precision':int(r['where_prec']),'date':r['date_start'][:10],'end':r['date_end'][:10],'best':int(r['best']),'low':int(r['low']),'high':int(r['high']),'sources':r['source_office'],'status':r['code_status']})
for event in events:
    event['source_code']=event['code']
    if event['region'] in ['Gaza Strip','West Bank']:
        event['code']='PSE'
root.joinpath('data/events.json').write_text(json.dumps(events,ensure_ascii=False,separators=(',',':')))
places=[]
specs=[('Suez','Canal de Suez',32.35,30.35,'stratégique','Relie la Méditerranée à la mer Rouge. Son rôle se comprend à l’échelle des échanges entre Europe et Asie.'),('Ormuz','Détroit d’Ormuz',56.4,26.6,'stratégique','Passage maritime entre le golfe Persique et le golfe d’Oman, essentiel au transport des hydrocarbures.'),('Malacca','Détroit de Malacca',101.5,2.5,'stratégique','Une voie maritime entre l’océan Indien et les mers d’Asie orientale.'),('Panama','Canal de Panama',-79.7,9.1,'stratégique','Relie les océans Atlantique et Pacifique. La disponibilité de l’eau compte dans son fonctionnement.'),('Bosphore','Bosphore',29.05,41.12,'stratégique','Relie la mer Noire à la mer de Marmara et sépare les deux rives d’Istanbul.'),('Bab-el-Mandeb','Bab-el-Mandeb',43.3,12.6,'stratégique','Relie la mer Rouge au golfe d’Aden, entre le Yémen et la Corne de l’Afrique.'),('Gibraltar','Détroit de Gibraltar',-5.6,35.95,'stratégique','Passage entre l’Atlantique et la Méditerranée, au voisinage de l’Europe et de l’Afrique.'),('Nil','Nil',31.3,25.7,'nature','Un grand système fluvial partagé par plusieurs États. Ses eaux soutiennent des activités agricoles et des populations nombreuses.'),('Amazone','Amazone',-60,-3,'nature','Un immense bassin fluvial sud-américain associé à la forêt amazonienne.'),('Himalaya','Himalaya',85,28,'nature','Une haute chaîne de montagnes issue de la collision des plaques indienne et eurasienne.'),('Sahara','Sahara',10,23,'nature','Un vaste désert chaud d’Afrique du Nord, traversé depuis des siècles par des réseaux de circulation.'),('Andes','Andes',-70,-20,'nature','Une chaîne de montagnes qui longe l’ouest de l’Amérique du Sud et façonne ses climats et ses communications.')]
for i,(s,n,lo,la,k,t) in enumerate(specs):places.append({'short':s,'name':n,'lon':lo,'lat':la,'kind':k,'intro':t,'article':'place_'+str(i)})
places+=json.load(open(root/'data/history.json'))
root.joinpath('data/places.json').write_text(json.dumps(places,ensure_ascii=False))
conflict_specs=[('Ukraine et Russie',['UKR','RUS'],0,'1991 · Indépendance de l’Ukraine|2014 · Annexion de la Crimée par la Russie et début du conflit dans le Donbass|2022 · Invasion russe à grande échelle'),('Soudan',['SDN'],1,'1956 · Indépendance|2019 · Chute d’Omar el-Béchir|2021 · Coup d’État|2023 · Début de la guerre entre l’armée et les Forces de soutien rapide'),('Israël et Palestine',['ISR','PSE'],2,'1947 · Plan de partage proposé par l’ONU|1948 · Création d’Israël, guerre et exode palestinien|1967 · Guerre et occupation de territoires par Israël|1993 · Accords d’Oslo|2023 · Attaques du 7 octobre et guerre à Gaza'),('Birmanie',['MMR'],3,'1948 · Indépendance|1962 · Coup d’État militaire|2021 · Coup d’État et extension de la guerre civile'),('Sahel',['MLI','NER','BFA'],4,'2012 · Rébellion et prise de territoires au Mali|2013 · Intervention militaire française|Années 2010 · Extension des violences au Sahel central'),('Est de la RD Congo',['COD'],5,'1994 · Génocide des Tutsi au Rwanda et déplacements régionaux|1996–2003 · Guerres du Congo|Années 2000–2020 · Persistance des rébellions à l’est'),('Yémen',['YEM'],6,'1990 · Unification|2011 · Soulèvement politique|2014 · Prise de Sanaa par les Houthis|2015 · Intervention d’une coalition menée par l’Arabie saoudite'),('Syrie',['SYR'],7,'2011 · Soulèvement, répression et début de la guerre|2015 · Intervention militaire russe|2024 · Chute du régime de Bachar el-Assad'),('Somalie',['SOM'],8,'1960 · Indépendance et unification|1991 · Chute du régime de Siad Barre|Années 2000 · Montée d’Al-Shabaab'),('Colombie',['COL'],9,'Années 1960 · Formation des FARC et de l’ELN|2016 · Accord de paix avec les FARC|Après 2016 · Persistance de groupes armés'),('Bassin du lac Tchad',['NGA','TCD','CMR','NER'],10,'2009 · Début de l’insurrection de Boko Haram|Années 2010 · Extension régionale des violences|2016 · Scission entre factions'),('Cachemire',['IND','PAK'],11,'1947 · Partition de l’Inde britannique et première guerre|1972 · Accord de Simla|2019 · Révocation du statut spécial du Jammu-et-Cachemire'),('Question kurde en Turquie',['TUR'],12,'1923 · Fondation de la République de Turquie|1984 · Début de l’insurrection armée du PKK|Années 2010 · Alternance de négociations et de reprise des combats'),('Pakistan',['PAK','AFG'],13,'2001 · Guerre en Afghanistan et recompositions régionales|2007 · Formation du TTP|Années 2010–2020 · Insurrection et opérations militaires'),('Haïti',['HTI'],14,'1804 · Indépendance|2010 · Séisme majeur|2021 · Assassinat du président Jovenel Moïse|Années 2020 · Extension du contrôle de groupes armés'),('Cameroun anglophone',['CMR'],15,'1961 · Réunification d’une partie du Cameroun britannique avec le Cameroun|2016 · Manifestations anglophones|2017 · Escalade du conflit séparatiste'),('Cabo Delgado',['MOZ'],16,'1975 · Indépendance du Mozambique|2017 · Début de l’insurrection à Cabo Delgado|2021 · Interventions militaires régionales')]
root.joinpath('data/conflicts.json').write_text(json.dumps([{'name':n,'codes':c,'article':'conflict_'+str(i),'timeline':t.split('|')} for n,c,i,t in conflict_specs],ensure_ascii=False))
print(len(events),'events',len(places),'places')
